'use strict';
const artists=window.ARTISTS,main=document.querySelector('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const themes={all:'All perspectives',identity:'Identity & community',power:'Power & politics',nature:'Nature & place',experiment:'Experiment & perception',popular:'Popular culture'};
const themeIds={identity:['01','02','07','10','14','15','19','23','25','27','31','33','34','36','39','40','42','45','51'],power:['02','04','05','08','15','18','20','21','22','29','31','33','34','37','39','40','42','51'],nature:['01','06','11','13','14','18','19','21','28','41','43','46'],experiment:['03','04','06','07','09','11','12','16','17','22','27','28','32','35','37','38','41','43','44','45','47','48','50'],popular:['05','08','12','13','23','24','25','26','29','30','49','51']};
let view='explore',current=null,query='',theme='all',medium='all',page=0,era='all',eventPage=0,game=null,brief=null;
let discoveries=new Set(),compareIds=['41','20'];
try{discoveries=new Set(JSON.parse(sessionStorage.getItem('art-context-discoveries')||'[]').filter(id=>artists.some(a=>a.id===id)));const stored=JSON.parse(sessionStorage.getItem('art-context-compare')||'null');if(Array.isArray(stored)&&stored.length===2&&stored.every(id=>artists.some(a=>a.id===id)))compareIds=stored;}catch{discoveries=new Set()}
function persist(key,value){try{sessionStorage.setItem('art-context-'+key,JSON.stringify(value));return true}catch{return false}}
function announce(s){document.querySelector('#announce').textContent=s}
function initials(a){return a.name==='Banksy'?'?':a.name.split(' ').slice(0,2).map(x=>x[0]).join('')}
function byId(id){return artists.find(a=>a.id===id)}
function featuredArtwork(a){const g=a.gallery.find(g=>g.workKey===a.featuredWork?.key);if(!g)throw new Error('Featured artwork is missing for '+a.name);return g}
function cardImage(a){return featuredArtwork(a).path}
function counts(){document.querySelector('#compare-count').textContent=compareIds.length}
function stop(){if('speechSynthesis'in window)speechSynthesis.cancel();document.querySelector('#stop').hidden=true}
function start(next){stop();view=next;document.querySelectorAll('nav button').forEach(b=>{const on=b.dataset.view===(next==='artist'?'explore':next);b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});counts()}
function focusMain(){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}
function listenButton(text,label='Listen',small=false){return `<button class="button secondary ${small?'small':''}" data-speak="${esc(text)}">◖)) ${esc(label)}</button>`}
function voice(){if(!('speechSynthesis'in window))return null;return speechSynthesis.getVoices().find(v=>v.localService&&v.lang.toLowerCase().startsWith('en'))||null}
function voiceStatus(){const ok=Boolean(voice());document.querySelectorAll('[data-speak]').forEach(b=>{b.disabled=!ok;if(ok)b.removeAttribute('title');else b.title='An installed local English voice is required.'});document.querySelectorAll('[data-voice-note]').forEach(n=>n.textContent=ok?'Read at your pace, or listen with a voice on this device.':'A local English voice is unavailable on this device. All text is available to read.');}
function speak(text){const v=voice();if(!v)return;stop();const u=new SpeechSynthesisUtterance(text);u.voice=v;u.lang=v.lang;u.rate=.94;u.onend=u.onerror=()=>document.querySelector('#stop').hidden=true;speechSynthesis.speak(u);document.querySelector('#stop').hidden=false;}
function explore(focus=true){start('explore');current=null;const hero=featuredArtwork(byId('41'));main.innerHTML=`<section class="hero"><div><p class="kicker"><span class="tiny-dot" aria-hidden="true"></span>51 ARTISTS · SIX CENTURIES · GRADES 7–8</p><h1>Look closer.<br><em>Think bigger.</em></h1><p class="hero-copy">Art records lives. Challenges power. Changes the way we see. Meet the artists, unpack their ideas, and build a perspective of your own.</p><div class="actions"><button class="button" data-action="surprise">Find a new perspective</button><button class="button secondary" data-view="challenges">Take the timeline challenge</button></div></div><div class="hero-art"><img src="${esc(hero.path)}" alt="${esc(hero.alt)}"><div class="hero-note"><b>51</b>different<br>perspectives</div><div class="art-caption"><strong>A wave that travelled<br>around the world.</strong><span>Hokusai · The Great Wave · c. 1830–1832<br>Explore images, ideas, and their impact.</span></div></div></section><section class="topic-strip" aria-label="Ways into the collection"><button data-topic="identity"><span class="symbol" aria-hidden="true">◎</span><strong>Whose story gets told?</strong><span>Identity, representation, and belonging.</span></button><button data-topic="power"><span class="symbol" aria-hidden="true">✳</span><strong>Can an image challenge power?</strong><span>Public space, protest, and patronage.</span></button><button data-topic="experiment"><span class="symbol" aria-hidden="true">◈</span><strong>What counts as art?</strong><span>New materials. Different ways of seeing.</span></button></section><section aria-labelledby="browse-title"><div class="section-head"><div><p class="kicker">THE ARTIST INDEX</p><h2 id="browse-title">Choose your starting point.</h2><p>Follow a question, a medium, or an artist who catches your eye.</p></div><span class="count" id="result-count"></span></div><div class="browse-controls"><label><span class="sr-only">Search artists, movements, media, and places</span><input type="search" id="artist-search" placeholder="Search an artist, movement, medium, or place…" value="${esc(query)}"></label><label><span class="sr-only">Filter by medium</span><select id="medium-filter"><option value="all">All media</option><option value="painting">Painting & fresco</option><option value="sculpture">Sculpture & installation</option><option value="print">Printmaking</option><option value="photo">Photography</option><option value="mixed">Mixed media & textiles</option></select></label></div><div class="filters" role="group" aria-label="Filter by perspective">${Object.entries(themes).map(([id,label])=>`<button class="filter" data-theme="${id}" aria-pressed="${theme===id}">${label}</button>`).join('')}</div><div id="artist-results"></div></section><section class="studio-banner"><div><p class="kicker">MAKE SOMETHING WORTH TALKING ABOUT</p><h2>Your next idea starts with a question.</h2><p>Try a creative brief. Compare two artists. Discuss a claim you can support.</p></div><button class="button accent" data-view="challenges">Enter the challenge lab</button></section>`;document.querySelector('#medium-filter').value=medium;renderResults();document.querySelector('#artist-search').addEventListener('input',e=>{query=e.target.value;page=0;renderResults()});document.querySelector('#medium-filter').addEventListener('change',e=>{medium=e.target.value;page=0;renderResults()});if(focus)focusMain()}
function mediaMatch(a){const m=a.media.join(' ').toLowerCase();return medium==='all'||medium==='painting'&&/paint|fresco|tempera|watercolour/.test(m)||medium==='sculpture'&&/sculpture|installation|construction/.test(m)||medium==='print'&&/print|etching|woodblock/.test(m)||medium==='photo'&&a.media.includes('Photography')||medium==='mixed'&&/mixed|textile|glass|digital/.test(m)}
function filtered(){const q=query.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return artists.filter(a=>(theme==='all'||themeIds[theme].includes(a.id))&&mediaMatch(a)&&[a.name,a.movement,a.place,a.media.join(' '),a.intro,...a.works.map(w=>w.title)].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q))}
function renderResults(){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/12));page=Math.min(page,pages-1);document.querySelector('#result-count').textContent=`${list.length} OF 51 ARTISTS`;document.querySelector('#artist-results').innerHTML=`<div class="grid">${list.length?list.slice(page*12,page*12+12).map(a=>`<button class="artist-card" data-artist="${a.id}" aria-label="Explore ${esc(a.name)}"><div class="card-image">${cardImage(a)?`<img class="${a.gallery.length?'':'portrait'}" src="${esc(cardImage(a))}" alt="" loading="lazy">`:`<div class="initial-poster" aria-hidden="true">${esc(initials(a))}</div>`}<span class="image-type">${a.gallery.length?a.gallery.length+' ARTWORK IMAGES':a.portrait?'PORTRAIT · 0 ARTWORK IMAGES':'0 ARTWORK IMAGES'}</span>${discoveries.has(a.id)?'<span class="card-marker" aria-label="Challenge completed">✓</span>':''}</div><div class="card-body"><p class="period">${esc(a.movement)}</p><h3>${esc(a.name)}</h3><p class="card-work"><span class="sr-only">Featured artwork: </span>${esc(featuredArtwork(a).title)}</p><p class="meta">${esc(a.dates)}<br>${esc(a.media.slice(0,2).join(' · '))}</p></div></button>`).join(''):`<div class="results-empty"><h3>No artists match that combination.</h3><p>Try a shorter search or clear the filters.</p><button class="button secondary" data-action="reset-filters">Reset filters</button></div>`}</div>${list.length?`<div class="pager"><button class="button secondary small" data-action="prev-artists" ${page===0?'disabled':''}>Previous</button><span>Page ${page+1} of ${pages}</span><button class="button secondary small" data-action="next-artists" ${page===pages-1?'disabled':''}>Next artists</button></div>`:''}`;}
function rightsLabel(g){return g.license||(g.licenseUrl?'See linked source licence.':'Public-domain designation; see source record.')}
function creditHTML(g){return `<details class="credit"><summary>Image credit & study-use details</summary><p>${esc(g.credit)}<br>${esc(g.changes||'Resized for this gallery.')}<br>Source: ${esc(g.source)}<br>Rights: ${esc(rightsLabel(g))}${g.licenseUrl?'<br>Rights reference: '+esc(g.licenseUrl):''}${g.copyrightNotice?'<br>'+esc(g.copyrightNotice):''}${g.rightsBasis?'<br>Use basis: '+esc(g.rightsBasis):''}${g.dateSource?'<br>Artwork date source: '+esc(g.dateSource):''}${g.infoSources?.some(u=>u!==g.source)?'<br>Artwork information sources: '+g.infoSources.filter(u=>u!==g.source).map(esc).join(' · '):''}</p></details>`}

function artworkPanel(a,g,index){return `<figure class="art-panel" data-featured-work-key="${esc(g.workKey)}"><button data-enlarge="${index}" aria-label="Enlarge ${esc(g.title)}"><img src="${esc(g.path)}" alt="${esc(g.alt)}"></button><figcaption><span class="label">Featured artwork</span><h2 class="featured-work-title">${esc(g.title)}</h2>${esc(g.date||'Date not verified')} · ${esc(a.name)}<br><span class="small-copy">Tap the image to look closer.</span>${artworkInfo(a,g,'h3')}${creditHTML(g)}</figcaption></figure>`}
function profile(id){const a=byId(id);if(!a)return;start('artist');current=a;const featured=featuredArtwork(a);const order=[Number(id)%3,(Number(id)+2)%3,(Number(id)+1)%3];const avatar=a.portrait?`<figure class="artist-portrait"><button class="portrait-open" data-action="view-portrait" aria-label="Enlarge portrait of ${esc(a.name)}"><img class="avatar" src="${esc(a.portrait.path)}" alt="Portrait of ${esc(a.name)}"><span class="portrait-hint">Enlarge portrait</span></button></figure>`:`<span class="avatar initial-avatar" aria-label="${a.name==='Banksy'?'Anonymous artist symbol':'Initials; no portrait is included'}">${esc(initials(a))}</span>`;main.innerHTML=`<button class="back" data-view="explore">Back to the artist index</button><div class="profile-head"><div class="profile-ident">${avatar}<div><p class="kicker">${esc(a.movement)}</p><h1>${esc(a.name)}</h1><p class="meta">${esc(a.dates)} · ${esc(a.place)}</p></div></div><div class="actions">${listenButton(a.name+'. '+a.intro+' Media: '+a.media.join(', '))}<button class="button accent" data-action="view-gallery">View artwork gallery (${a.gallery.length})</button><button class="button secondary" data-compare="${a.id}">Compare this artist</button></div></div><div class="profile-overview"><div>${a.gallery.length?artworkPanel(a,featured,a.gallery.indexOf(featured)):`<section class="portrait-study"><p class="kicker">START WITH THE ARTIST</p>${a.portrait?`<img src="${esc(a.portrait.path)}" alt="Portrait of ${esc(a.name)}">`:`<div class="large-initial" aria-hidden="true">${esc(initials(a))}</div>`}<h2>Read the work.<br>Question the context.</h2><p>This edition includes written studies of significant works below. No unverified artwork reproduction or substitute is presented as an original.</p>${a.portrait?creditHTML(a.portrait):''}</section>`}</div><section class="profile-summary"><p class="kicker">THE QUICK TAKE</p><p class="lead">${esc(a.intro)}</p><span class="label">Media & materials</span><div class="chips">${a.media.map(m=>`<button class="chip" data-medium="${esc(m)}" aria-label="Explain ${esc(m)}">${esc(m)}</button>`).join('')}</div><div class="movement"><span class="label">Something worth knowing</span><ul class="profile-facts">${a.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div><p class="voice-note" data-voice-note></p>${a.portrait?creditHTML(a.portrait):''}</section></div>${galleryMarkup(a)}<div class="content-grid"><section class="panel"><p class="kicker">A CAREER IN CONTEXT</p><h2>Three moments on the timeline.</h2><ol class="mini-timeline">${a.timeline.map(t=>`<li><span class="year">${esc(t.dateLabel||t.year)}</span><span>${esc(t.text)}</span></li>`).join('')}</ol><div class="actions"><button class="button secondary small" data-view="timeline">See the bigger timeline</button></div></section><section class="panel mint"><p class="kicker">LOOK · INTERPRET · QUESTION</p><h2>What would you ask?</h2><p>${esc(a.quiz.question)}</p><p class="small-copy">Start with visible evidence. Then use historical context. Separate a documented fact from a personal interpretation.</p>${listenButton(a.quiz.question,'Read the question',true)}</section></div><section style="margin-top:35px" aria-labelledby="works-title"><div class="section-head"><div><p class="kicker">FAMOUS & SIGNIFICANT WORKS</p><h2 id="works-title">More than a title.</h2></div></div><p class="work-status">${esc(a.workStatus)} Dates can refer to a series, an edition, or a documented event; those distinctions are identified.</p><div class="work-studies">${a.works.map(w=>`<article class="work-study">${workStudyThumbnail(a,w)}<h3>${esc(w.title)}</h3><div class="work-date">${esc(w.date)} · ${esc(w.medium)}</div><p>${esc(w.description)}</p></article>`).join('')}</div></section><div class="content-grid"><section class="panel lime"><p class="kicker">ART & SOCIETY</p><h2>Why did it matter beyond the studio?</h2><p>${esc(a.society)}</p><p class="analysis-label">Educational synthesis · consider other viewpoints</p>${listenButton(a.society,'Listen to this context',true)}</section><section class="panel"><p class="kicker">ART & HISTORY</p><h2>What changed in art?</h2><p>${esc(a.history)}</p><p class="analysis-label">Influence is shared; movements overlap</p>${listenButton(a.history,'Listen to this context',true)}</section></div><div class="content-grid single"><section class="panel lilac"><p class="kicker">CHECK YOUR PERSPECTIVE</p><h2>A question with context.</h2><p>${esc(a.quiz.question)}</p><div class="answer-list">${order.map(i=>`<button class="answer" data-answer="${i}" aria-label="${esc(a.quiz.answers[i])}">${esc(a.quiz.answers[i])}</button>`).join('')}</div><p class="feedback" id="quiz-feedback" role="status">${discoveries.has(a.id)?'You have already completed this challenge. You can revisit it.':''}</p>${listenButton(a.quiz.question+' Choices: '+a.quiz.answers.join(' '),'Read question & choices',true)}</section></div><details class="profile-source"><summary>Sources & a note on interpretation</summary><p>Biographical and work references are listed below as plain text. The impact paragraphs are educational interpretations based on this context; they are not direct quotations or a claim that a single artist caused a historical change.</p>${a.sources.map(s=>`<p>${esc(s)}</p>`).join('')}</details>`;voiceStatus();focusMain()}
const eras={all:['All dates',0,3000],early:['1400–1699',1400,1699],long:['1700–1899',1700,1899],modern:['1900–1949',1900,1949],now:['1950–today',1950,3000]};
function timeline(){start('timeline');const all=artists.flatMap(a=>a.timeline.map(t=>({...t,artist:a}))).sort((a,b)=>a.year-b.year||a.artist.name.localeCompare(b.artist.name));const range=eras[era];const filtered=all.filter(t=>t.year>=range[1]&&t.year<=range[2]);const pages=Math.max(1,Math.ceil(filtered.length/18));eventPage=Math.min(eventPage,pages-1);main.innerHTML=`<section class="page-intro"><p class="kicker">ART DOESN’T HAPPEN IN A VACUUM</p><h1>Put the ideas<br><em>in order.</em></h1><p>Follow career moments across centuries. Notice who was working at the same time, and which approaches continued alongside newer ones.</p></section><div class="timeline-tools" role="group" aria-label="Choose a timeline period">${Object.entries(eras).map(([id,[label]])=>`<button class="filter" data-era="${id}" aria-pressed="${id===era}">${label}</button>`).join('')}</div><p class="small-copy">${filtered.length} documented career moments. Approximate dates and decade labels are identified; this is not a complete world history of art.</p><div class="event-list">${filtered.slice(eventPage*18,eventPage*18+18).map(t=>`<article class="event"><div class="event-year">${esc(t.dateLabel||t.year)}</div><div><button data-artist="${t.artist.id}">${esc(t.artist.name)}</button><p>${esc(t.text)}</p></div><span class="event-tag">${esc(t.artist.movement)}</span></article>`).join('')}</div><div class="pager"><button class="button secondary small" data-action="prev-events" ${eventPage===0?'disabled':''}>Previous</button><span>Page ${eventPage+1} of ${pages}</span><button class="button secondary small" data-action="next-events" ${eventPage===pages-1?'disabled':''}>Next moments</button></div><section class="studio-banner"><div><h2>Think you’ve got the sequence?</h2><p>Try arranging three art-history moments without seeing the dates.</p></div><button class="button accent" data-view="challenges">Play timeline mix-up</button></section>`;focusMain()}
function compare(){start('compare');const chosen=compareIds.map(byId);main.innerHTML=`<section class="page-intro"><p class="kicker">TWO ARTISTS. BETTER QUESTIONS.</p><h1>Different media.<br><em>Shared questions?</em></h1><p>Compare materials, context, and ideas. Similar-looking work can have different purposes; very different work can ask related questions.</p></section><div class="compare-pickers">${chosen.map((a,i)=>`<label>Artist ${i+1}<select aria-label="Artist ${i+1}" data-compare-select="${i}">${artists.map(x=>`<option value="${x.id}" ${a.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`).join('')}</div><div class="compare-grid">${chosen.map(a=>`<article class="compare-card">${cardImage(a)?`<img src="${esc(cardImage(a))}" alt="${esc(featuredArtwork(a).alt)}">`:`<div class="initial-compare">${esc(initials(a))}</div>`}<p class="kicker">${esc(a.dates)}</p><h2>${esc(a.name)}</h2><p class="small-copy">${esc(featuredArtwork(a).title)}</p><span class="label">Media</span><div class="chips">${a.media.map(m=>`<button class="chip" data-medium="${esc(m)}" aria-label="Explain ${esc(m)}">${esc(m)}</button>`).join('')}</div><span class="label">Context</span><p>${esc(a.intro)}</p><span class="label">Art & society</span><p>${esc(a.society)}</p><button class="button secondary small" data-artist="${a.id}">Explore this artist</button></article>`).join('')}</div><section class="reflection"><p class="kicker">THE COMPARISON CHALLENGE</p><h2>Go beyond “they both use colour.”</h2><p>What can one medium do that the other cannot? How does each artist’s setting or audience affect the work? Name one meaningful connection, then support it with evidence from both.</p></section>`;main.querySelectorAll('[data-compare-select]').forEach(s=>s.addEventListener('change',e=>{const i=Number(e.target.dataset.compareSelect),id=e.target.value;if(compareIds[1-i]===id){announce('Choose a different artist for each side.');e.target.value=compareIds[i];return}compareIds[i]=id;persist('compare',compareIds);compare()}));focusMain()}
const gameBank=[['The Night Watch',1642,'45'],['A Sunday on La Grande Jatte is exhibited',1886,'28'],['Surprised! (Tiger in a Tropical Storm)',1891,'11'],['The Scream',1893,'38'],['Composition VIII',1923,'44'],['Castle and Sun',1928,'35'],['American Gothic',1930,'21'],['Migrant Mother',1936,'15'],['Guernica',1937,'22'],['Les Fétiches',1938,'10'],['The Migration Series is completed',1941,'42'],['Christina’s World',1948,'19'],['Campbell’s Soup Cans',1962,'26'],['Cakes',1963,'30'],['A Bigger Splash',1967,'43'],['Hollywood Africans',1983,'51'],['Tar Beach',1988,'39'],['Tuttomondo',1989,'08'],['Puppy',1992,'24'],['Michelle Obama portrait is unveiled',2018,'40']];
function newGame(){const pool=[...gameBank].sort(()=>Math.random()-.5).slice(0,3);game={cards:pool.map((x,i)=>({title:x[0],year:x[1],id:x[2],key:String(i)})),picked:[],message:'Choose the earliest work or event first. No timer, and you can rethink an answer.'};}
const briefs={identity:['Create a portrait that shows a role, community, or interest without relying on a realistic face.','Create a small visual autobiography using five objects and one deliberate omission.'],power:['Design a poster for a positive change you want to see in your school. Make the intended audience clear.','Propose a mural about whose stories are missing from a shared space. Use your own symbols.'],nature:['Show a familiar landscape changed by human choices. Decide what you want viewers to notice.','Make two views of the same place: one describes its appearance; the other communicates your experience of it.'],experiment:['Represent a piece of music using only line, shape, and colour. Explain which visual choices connect to the sound.','Make a study of one ordinary object from three viewpoints or moments, then combine them.']};
const constraints=['Use only two colours plus black and white.','Make repetition part of the meaning, not just decoration.','Include a change of scale that supports your message.','Use negative space as an important part of the design.','Combine one word with an image without simply labelling it.'];
function makeBrief(kind='identity'){brief={kind,text:briefs[kind][Math.floor(Math.random()*briefs[kind].length)],constraint:constraints[Math.floor(Math.random()*constraints.length)]}}
function challenges(){start('challenges');if(!game)newGame();if(!brief)makeBrief();main.innerHTML=`<section class="page-intro"><p class="kicker">THE CHALLENGE LAB</p><h1>Play with ideas.<br><em>Keep the evidence.</em></h1><p>Test your timeline instincts, then turn a question into a creative response. You don’t need a perfect drawing to have a worthwhile idea.</p></section><section class="panel lilac"><div class="section-head"><div><p class="kicker">TIMELINE MIX-UP</p><h2>Oldest first. What’s your order?</h2></div><button class="button secondary small" data-action="new-game">New round</button></div><div class="progress-track" aria-label="${game.picked.length} of 3 events placed"><span style="width:${game.picked.length/3*100}%"></span></div><div class="game-options">${game.cards.map(c=>`<button class="game-choice ${game.picked.includes(c.key)?'selected':''}" data-game="${c.key}" ${game.picked.includes(c.key)?'disabled':''}><strong>${esc(c.title)}</strong>${esc(byId(c.id).name)}<small>${game.picked.includes(c.key)?c.year+' · placed in sequence':'Date hidden · choose in chronological order'}</small></button>`).join('')}</div><p class="game-feedback" role="status">${esc(game.message)}</p></section><section style="margin-top:36px"><div class="section-head"><div><p class="kicker">YOUR CREATIVE BRIEF</p><h2>A constraint can unlock an idea.</h2></div></div><div class="challenge-controls"><label><span class="sr-only">Creative brief theme</span><select id="brief-theme"><option value="identity">Identity & belonging</option><option value="power">A message for change</option><option value="nature">Nature & place</option><option value="experiment">Experiment & perception</option></select></label><button class="button secondary" data-action="new-brief">Remix the brief</button></div><div class="brief"><p class="kicker">MAKE YOUR OWN RESPONSE</p><p>${esc(brief.text)}</p><span class="constraint">${esc(brief.constraint)}</span><p class="small-copy" style="margin-top:17px">Work on paper or with your school’s approved art tools. Use your own experiences and symbols; research cultural context rather than copying sacred imagery.</p>${listenButton(brief.text+' '+brief.constraint,'Read the brief',true)}</div><div class="rubric"><div><strong>Intent</strong><p>Who is the audience? What question or message drives your work?</p></div><div><strong>Choices</strong><p>How do the medium, composition, and visual details support that intent?</p></div><div><strong>Reflection</strong><p>What would you change after hearing another viewer’s interpretation?</p></div></div></section>`;main.querySelector('#brief-theme').value=brief.kind;main.querySelector('#brief-theme').addEventListener('change',e=>{makeBrief(e.target.value);challenges()});voiceStatus();focusMain()}
function route(next){if(next==='explore')explore();if(next==='timeline')timeline();if(next==='compare')compare();if(next==='challenges')challenges();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view){route(b.dataset.view);return}if(b.dataset.artist){if(document.querySelector('#teacher').open)document.querySelector('#teacher').close();profile(b.dataset.artist);return}if(b.dataset.medium){explainMedium(b.dataset.medium);return}if(b.dataset.speak){speak(b.dataset.speak);return}if(b.dataset.theme){theme=b.dataset.theme;page=0;main.querySelectorAll('[data-theme]').forEach(x=>x.setAttribute('aria-pressed',x===b));renderResults();announce(`${filtered().length} ${filtered().length===1?'artist matches':'artists match'}`);return}if(b.dataset.topic){theme=b.dataset.topic;query='';medium='all';page=0;explore(false);main.querySelector('#browse-title').scrollIntoView({block:'start'});main.querySelector(`[data-theme="${theme}"]`).focus({preventScroll:true});return}if(b.dataset.era){era=b.dataset.era;eventPage=0;timeline();return}if(b.dataset.compare){if(compareIds.includes(b.dataset.compare)){compare()}else{compareIds=[compareIds[1],b.dataset.compare];persist('compare',compareIds);compare()}return}if(b.dataset.enlarge!==undefined&&current){openArtwork(Number(b.dataset.enlarge));return}if(b.dataset.answer!==undefined&&current){const correct=Number(b.dataset.answer)===current.quiz.correct;const feedback=document.querySelector('#quiz-feedback');if(correct){b.classList.add('correct');discoveries.add(current.id);persist('discoveries',[...discoveries]);feedback.textContent='Connection made. '+current.quiz.answers[current.quiz.correct]+' Consider how the evidence supports this idea.';main.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true)}else{b.classList.add('wrong');feedback.textContent='Reconsider the context above, then try another answer. A convincing explanation needs evidence.'}return}if(b.dataset.game!==undefined){const c=game.cards.find(x=>x.key===b.dataset.game),next=game.cards.filter(x=>!game.picked.includes(x.key)).sort((a,b)=>a.year-b.year)[0];if(c.key===next.key){game.picked.push(c.key);game.message=game.picked.length===3?'Sequence solved: '+[...game.cards].sort((a,b)=>a.year-b.year).map(x=>x.year+' · '+x.title).join(' / '):`${c.year}: ${c.title}. Now choose the next event.`}else game.message='That is not the earliest remaining event. Compare the artists’ periods and try again.';const y=window.scrollY;challenges();window.scrollTo({top:y,behavior:'instant'});return}const action=b.dataset.action;if(action==='view-portrait'){openPortrait();return}if(action==='view-gallery'){const target=main.querySelector('#gallery-title');target?.scrollIntoView({block:'start'});target?.focus({preventScroll:true});return}if(action==='surprise')profile(artists[Math.floor(Math.random()*artists.length)].id);if(action==='reset-filters'){query='';theme='all';medium='all';page=0;explore(false);main.querySelector('#artist-search').focus()}if(action==='prev-artists'||action==='next-artists'){page+=action==='next-artists'?1:-1;renderResults();main.querySelector('#browse-title').scrollIntoView({block:'start'});main.querySelector('.artist-card')?.focus({preventScroll:true})}if(action==='prev-events'||action==='next-events'){eventPage+=action==='next-events'?1:-1;timeline()}if(action==='new-game'){newGame();const y=window.scrollY;challenges();window.scrollTo({top:y,behavior:'instant'})}if(action==='new-brief'){const y=window.scrollY;makeBrief(brief.kind);challenges();window.scrollTo({top:y,behavior:'instant'})}if(action==='teacher'){stop();document.querySelector('#teacher').showModal()}if(action==='close-teacher')document.querySelector('#teacher').close();if(action==='clear-session'){askConfirmation('Reset this tab’s completed context challenges?',()=>{discoveries.clear();try{sessionStorage.removeItem('art-context-discoveries')}catch{}document.querySelector('#teacher-status').textContent='Completed challenges reset for this tab.';if(view==='explore')renderResults();if(view==='artist'){main.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=false;b.classList.remove('correct','wrong')});const feedback=main.querySelector('#quiz-feedback');if(feedback)feedback.textContent=''}})}});
document.querySelector('#stop').onclick=stop;if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',voiceStatus);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',stop);
document.querySelector('#source-list').innerHTML=artists.map(a=>`<section class="source-entry"><h3>${esc(a.name)}</h3><p>${a.sources.map(esc).join('<br>')}</p><p><strong>Featured artwork: ${esc(featuredArtwork(a).title)}</strong><br>${esc(a.featuredWork.reason)}<br>${a.featuredWork.sources.map(esc).join('<br>')}</p><p><strong>Artwork image audit: ${a.gallery.length}/10</strong><br>${esc(a.galleryAudit.shortfallReason||'Ten distinct works available.')}</p>${a.galleryAudit.sourceChecks.map(s=>'<p>'+esc(typeof s==='string'?s:Object.values(s).join(' — '))+'</p>').join('')}${[...(a.portrait?[a.portrait]:[]),...a.gallery].map(g=>`<p><strong>${esc(g.title||'Artist portrait')}</strong><br>${esc(g.credit)}<br>${esc(g.changes||'Responsive display.')}<br>Source: ${esc(g.source)}<br>Rights: ${esc(rightsLabel(g))}${g.licenseUrl?'<br>Rights reference: '+esc(g.licenseUrl):''}${g.copyrightNotice?'<br>'+esc(g.copyrightNotice):''}${g.rightsBasis?'<br>Use basis: '+esc(g.rightsBasis):''}${g.rightsAssessment?'<br>Assessment: '+esc(typeof g.rightsAssessment==='string'?g.rightsAssessment:Object.entries(g.rightsAssessment).map(([k,v])=>k+': '+v).join(' | ')):''}${g.contentNote?'<br>Teacher preview note: '+esc(g.contentNote):''}${g.metadataSource?'<br>Work metadata source: '+esc(g.metadataSource):''}${g.imageSourcePage?'<br>Illustration source: '+esc(g.imageSourcePage):''}</p>`).join('')}</section>`).join('');
explore(false);

function explainMedium(label){
 const definitions=[[/fresco/i,'Pigment is applied to fresh lime plaster. As the plaster sets, the colour becomes part of the wall surface. This requires planning the sections that can be painted while they are wet.'],[/tempera/i,'Pigment is mixed with a binder, often egg in egg tempera. It can produce fine detail and carefully layered, quick-drying marks. Check the work record: not every paint called tempera uses egg.'],[/oil/i,'Pigments are mixed with a drying oil. The slower drying time allows blending, layering, and changes to the painted surface. The support might be wood, canvas, or another material.'],[/acrylic/i,'Pigments are held in an acrylic polymer binder. Acrylic paint usually dries quickly and can create thin washes or thick, opaque areas.'],[/watercolour/i,'Pigment and a water-soluble binder are applied with water, usually to paper. Transparent layers can let the brightness of the paper remain visible.'],[/woodblock/i,'A design is carved into a wooden block. Ink on the raised surface transfers to paper. Colour prints often require separate blocks and careful alignment.'],[/etching/i,'Lines are bitten into a metal plate using a controlled chemical process. Ink sits in the recessed lines and is transferred to paper under pressure.'],[/print/i,'An image is transferred from a prepared surface to another surface, usually paper. Processes include relief, intaglio, lithography, and screenprinting. An edition can contain multiple original impressions.'],[/photograph/i,'Light is recorded using a camera. Framing, timing, lighting, staging, processing, and editing can all influence what a photograph communicates.'],[/installation/i,'An arrangement of objects, materials, light, or sound creates an experience in a space. A viewer’s position and movement may be important parts of the work.'],[/glass/i,'Glass can act as a surface, a transparent layer, or a three-dimensional material. Light, reflection, and the viewer’s position can change what is visible.'],[/sculpture|clay/i,'Three-dimensional form can be carved, modelled, cast, assembled, or fabricated. A sculpture’s material and changing viewpoints can be central to its meaning.'],[/textile/i,'Fibres and fabrics are shaped through processes such as weaving, stitching, or assembling layers. A textile work can combine image, pattern, words, and physical texture.'],[/digital/i,'An artist uses electronic tools to create an image. The device offers a different set of marks, layers, editing options, and ways to share the result.'],[/mixed/i,'Two or more materials or processes are combined in a work. Ask what each material contributes rather than treating the combination as only decoration.'],[/mural/i,'An artwork is made for or attached to a wall. Its scale, architecture, location, and public audience help shape how it is understood. Fresco is one technique for making a mural.'],[/stencil/i,'A cut or blocked shape controls where pigment reaches a surface. The same stencil can repeat an image, while colour and location change its effect.'],[/drawing/i,'Marks made with tools such as pencil, chalk, charcoal, or ink investigate line, tone, form, and ideas. A drawing can be a plan or an independent artwork.'],[/film|performance/i,'An artwork unfolds through time. Movement, sequence, duration, and the relationship to an audience become artistic materials.'],[/writing/i,'Words can form part of an artist’s practice through books, poems, theories, captions, or statements. Text can work alongside an image or as a separate work.'],[/design/i,'Visual choices are organised for an object, communication, or space. Purpose, audience, materials, and production methods shape the result.'],[/paint/i,'Pigments held in a binder are applied to a surface. The binder, support, tools, and layering affect the result; compare the exact medium given for each work.']];
 const text=definitions.find(([re])=>re.test(label))?.[1]||'Check the specific artwork’s materials and process. The medium influences what an artist can make and how viewers experience it.';
 const d=document.createElement('dialog');d.setAttribute('aria-label',label+' explained');d.innerHTML=`<button class="close" aria-label="Close medium explanation">×</button><p class="kicker">MATERIALS MATTER</p><h2>${esc(label)}</h2><p>${esc(text)}</p>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal();
}

function askConfirmation(message,confirmed){
 const d=document.createElement('dialog');d.setAttribute('aria-label','Confirm challenge reset');d.innerHTML=`<p class="kicker">CONTEXT CHALLENGES</p><h2>Reset progress?</h2><p>${esc(message)}</p><div class="actions"><button class="button secondary" data-cancel>Keep progress</button><button class="button" data-confirm>Reset progress</button></div>`;document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=()=>{d.close();confirmed()};d.addEventListener('close',()=>d.remove());d.showModal();d.querySelector('[data-cancel]').focus();
}

function galleryMarkup(a){
 const total=a.gallery.length;
 return `<section class="artwork-gallery" id="artwork-gallery" aria-labelledby="gallery-title"><div class="section-head"><div><p class="kicker">ACTUAL ARTWORKS · LOOK CLOSELY</p><h2 id="gallery-title" tabindex="-1">${esc(a.name)}: artwork gallery</h2><p>Open a work to see it larger, read its title and date, and move through the gallery.</p></div><div class="gallery-total"><strong>${total}</strong><span>distinct work${total===1?'':'s'}</span></div></div><p class="gallery-coverage">${total>=10?'At least 10 distinct artwork images are available.':`${total} of the requested 10 artwork images ${total===1?'is':'are'} currently available. ${total===0?'We have not verified an image reproduction for this artist yet.':'This gallery is still below the requested minimum.'}`}</p>${total?`<div class="artwork-grid">${a.gallery.map((g,i)=>`<figure class="gallery-work" data-work-key="${esc(g.workKey||g.title)}"><button class="gallery-open" data-enlarge="${i}" aria-label="Open artwork ${i+1}: ${esc(g.title)}"><img src="${esc(g.path)}" alt="${esc(g.alt)}" loading="lazy" decoding="async"><span class="gallery-expand">View larger</span></button><figcaption><h3>${esc(g.title)}</h3><p class="gallery-date">${esc(g.date||'Date not verified')}${g.medium?' · '+esc(g.medium):''}</p>${artworkInfo(a,g)}${creditHTML(g)}</figcaption></figure>`).join('')}</div>`:`<div class="gallery-empty"><h3>No artwork images available in this edition yet.</h3><p>The written work studies below describe real works, but they are not image reproductions. The teacher desk lists this artist’s current image shortfall and the sources checked.</p></div>`}</section>`;
}
function openArtwork(index){
 const a=current;if(!a||!a.gallery[index])return;
 const d=document.createElement('dialog');d.className='art-dialog gallery-dialog';d.setAttribute('aria-label','Artwork viewer');d.innerHTML='<button class="close" aria-label="Close enlarged artwork">×</button><p class="kicker">ARTWORK VIEWER</p><h2 class="viewer-title"></h2><img class="viewer-image"><p class="viewer-meta"></p><div class="viewer-study"></div><div class="viewer-controls"><button class="button secondary small" data-previous>Previous artwork</button><span class="viewer-counter" aria-live="polite"></span><button class="button secondary small" data-next>Next artwork</button></div><div class="viewer-credit"></div>';
 const image=d.querySelector('.viewer-image'),previous=d.querySelector('[data-previous]'),next=d.querySelector('[data-next]');
 function refresh(){const g=a.gallery[index];image.src=g.path;image.alt=g.alt;d.querySelector('.viewer-title').textContent=g.title;d.querySelector('.viewer-meta').textContent=a.name+' · '+(g.date||'Date not verified')+(g.medium?' · '+g.medium:'');d.querySelector('.viewer-study').innerHTML=artworkInfo(a,g,'h3');d.querySelector('.viewer-counter').textContent=(index+1)+' of '+a.gallery.length;d.querySelector('.viewer-credit').innerHTML=creditHTML(g);previous.disabled=index===0;next.disabled=index===a.gallery.length-1;voiceStatus();}
 previous.onclick=()=>{if(index>0){index--;refresh();if(previous.disabled)next.focus()}};next.onclick=()=>{if(index<a.gallery.length-1){index++;refresh();if(next.disabled)previous.focus()}};d.querySelector('.close').onclick=()=>d.close();d.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'&&index>0){e.preventDefault();index--;refresh()}if(e.key==='ArrowRight'&&index<a.gallery.length-1){e.preventDefault();index++;refresh()}});d.addEventListener('close',()=>d.remove());document.body.append(d);refresh();d.showModal();
}
const coverage=document.createElement('details');coverage.id='coverage-details';coverage.innerHTML='<summary>Artwork image coverage: counts for all 51 artists</summary><p>Counts refer to distinct artworks, not artist photographs, duplicate views, details, or multiple casts of one composition. Original painted self-portraits count as artworks. The count includes openly licensed/public-domain images and images assessed for Canadian educational fair dealing. A shortfall means suitable images or source evidence are still needed; it does not mean the artist made no artwork.</p><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th scope="col">Artist</th><th scope="col">Images</th><th scope="col">Target</th><th scope="col">Status</th></tr></thead><tbody>'+artists.map(a=>'<tr><th scope="row"><button data-artist="'+a.id+'">'+esc(a.name)+'</button></th><td>'+a.gallery.length+'</td><td>10</td><td>'+(a.gallery.length>=10?'Target met':(10-a.gallery.length)+' still needed')+'</td></tr>').join('')+'</tbody></table></div><p>The repository’s ARTWORK-COVERAGE.md report gives exact counts, source checks, and remaining gaps.</p>';document.querySelector('#teacher').insertBefore(coverage,document.querySelector('#source-details'));

function workStudyThumbnail(a,w){
 const key=t=>String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\bthe\b/g,'').replace(/[^a-z0-9]/g,'');
 const years=t=>(String(t).match(/\b(?:1[4-9]\d{2}|20\d{2})\b/g)||[]).map(Number);const sy=years(w.date);const i=a.gallery.findIndex(g=>{if(key(g.studyTitle||g.title)!==key(w.title))return false;const gy=years(g.date);return !sy.length||!gy.length||Math.min(...sy)<=Math.max(...gy)&&Math.min(...gy)<=Math.max(...sy)});if(i<0)return '';
 const g=a.gallery[i];return `<button class="study-image" data-enlarge="${i}" aria-label="Enlarge ${esc(g.title)}"><img src="${esc(g.path)}" alt="${esc(g.alt)}" loading="lazy"></button>`;
}

function artworkInfo(a,g,heading='h4'){
 return `<div class="artwork-info"><${heading}>About this artwork</${heading}><p class="gallery-description">${esc(g.description)}</p>${listenButton(a.name+'. '+g.title+'. '+(g.date||'')+'. '+(g.medium||'')+'. '+g.description,'Listen to this artwork',true)}</div>`;
}
function openPortrait(){
 const a=current;if(!a?.portrait)return;const g=a.portrait,opener=document.activeElement;
 const d=document.createElement('dialog');d.className='art-dialog portrait-dialog';d.setAttribute('aria-labelledby','portrait-viewer-title');
 d.innerHTML=`<button class="close" aria-label="Close enlarged portrait">×</button><p class="kicker">MEET THE ARTIST</p><h2 id="portrait-viewer-title">${esc(a.name)}</h2><p class="portrait-dates">${esc(a.dates)}</p><img class="portrait-viewer-image" src="${esc(g.path)}" alt="${esc(g.alt||'Portrait of '+a.name)}"><p class="portrait-caption">Portrait of ${esc(a.name)}. ${esc(a.intro)}</p>${creditHTML(g)}`;
 d.querySelector('.close').onclick=()=>d.close();d.addEventListener('close',()=>{d.remove();opener?.focus()});document.body.append(d);d.showModal();
}
